-- Mod-authored victory and defeat screen descriptions, cs_CZ overlay.
-- Baseline in CivVAccess_VictoryDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_MISSING"] = "Pro tuto obrazovku není k dispozici žádný popis."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_CULTURAL"] =
    "Na travnatém návrší ve stínu tmavého stromu sedí dvě postavy v siluetě a dívají se na zlaté město. Pod nimi dav přechází přes klenutý kamenný most, lemovaný klasickými sochami na podstavcích, a za mostem se tyčí síň s kupolí. Za pásem parku se panorama města vypíná do štíhlých futuristických věží, které se rozplývají v jantarové mlze. Po trávnících jsou rozesety postavy lidí: děti běhají pod drakem, který vysoko stoupá na své šňůře, jedna postava se prochází pod žlutým slunečníkem a v mlze se na vzdálené vodě bělají plachty. Celá scéna je prozářena teplým zlatým světlem, napůl pozdním odpolednem a napůl snem, a po obloze jsou rozeseti ptáci."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DIPLOMATIC"] =
    "Obřad na zeleném trávníku před vysokou bílou deskou budovy sídla Organizace spojených národů. V popředí stojí dav zády k tobě, oblečený v oblecích, hábitech a šátcích z mnoha zemí, zatímco vpravo natáčí televizní kameraman s kamerou na stativu. Trávník obklopují stožáry s desítkami státních vlajek, mezi nimiž jsou rozpoznatelné vlajky Spojených států a Mexika. Uprostřed spočívá na čtvercovém podstavci pod rozložitými stromy velký kamenný glóbus s reliéfně vyvýšenými kontinenty. Před ním čeká řada dětí v lidových krojích různých zemí. Žena v modrém se sklání a podává cosi malé holčičce ve žlutých šatech, která se po tom natahuje. Červené a bílé květinové záhony lemují klidné jezírko u spodního okraje obrazu a měkké šedé denní světlo všechno rovnoměrně osvětluje."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DOMINATION"] =
    "Vítězná přehlídka namalovaná plakátovými barvami, samé zlato, olivová zeleň a červeň. V pravém popředí mladý důstojník v bílé slavnostní uniformě se zlatým prýmkem na rameni svírá žerď obrovské rudé vlajky, která se vlní přes oblohu, a jeho čepice s kšiltem má červený pásek a zlatý odznak. Za ním stojí řady vojáků ve stejných bílých uniformách s puškami s nasazenými bajonety, které drží svisle u ramene, a z kolony se zdvihají další rudé vlajky. Nad přehlídkou stojí na vysokém podstavci bronzová socha velitele na kráčejícím koni, za ní velká budova kapitolu s kupolí. Tenké rudé prapory vlají jako stuhy po zářivé žlutozelené obloze a dálku uzavírají tmavé cypřiše a mlhavé hory."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_SPACE_RACE"] =
    "Hluboký vesmír, pohled zdola vzhůru na obrovskou orbitální stanici. Její tmavý trup se táhne přes horní část obrazu, na spodní straně jsou řady vysokých teple osvětlených oken a zeleně zářících doků. Přes kov se vlečou chuchvalce páry. Ploché mřížkové solární panely se rozpínají od trupu na příhradových ramenech a dlouhá věžovitá příhradová konstrukce obložená panely klesá od vzdálenějšího konce stanice podél pravé strany obrazu. Dole se rozprostírá noční strana planety v hlubokém fialovém a vínovém odstínu a její horizont se klene přes spodek scény. Slunce právě vychází nad tímto horizontem v bílozlatém záblesku, který osvětluje pásy růžových a krémových mraků podél oblouku. V popředí přelétá tmou osamělá okřídlená loď po dlouhé zářivé tyrkysové brázdě a v dálce se proti hvězdám lesknou menší plavidla v zelené a oranžové barvě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_TIME"] =
    "Vlastní obal hry zvětšený tak, aby vyplnil obrazovku. Obraz ovládá glóbus slepený ze starých sépiových map, přes který se táhne nápis Sid Meier's Civilization ve vystouplých písmenech z leštěného kovu, provlečených obří mosaznou římskou pětkou. V levém horním rohu je nalepena obnošená finská poštovní známka, na které jezdec na zdobeném koni připomíná epos Kalevala. Kolem ní jsou otištěna slabá poštovní razítka. Za glóbem leží koláž z papíru zabarveného do tyrkysova, mosazný poledníkový kruh se klene kolem spodního okraje glóbu a světlo dopadá zleva shora, jako na kuriozitu pod lampou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_DEFEAT"] =
    "Mrtvá říše pod pouštní oblohou. Kolosální kamenná hlava sochy leží na tváři v písku, se zavřenýma očima a poklidným obličejem, zatímco opodál vyčnívá ze země rozbitá kamenná ruka s prsty zkroucenými k nebi. Kolem se rozkládá vykopávka: v popředí jsou do země vyhloubeny příkopy, stojí tu linie plotu ze sloupků a drátu a osamělá postava ve světlém oděvu stojí na dřevěné schodišťové plošině, malá proti tváři, kterou zkoumá. Vlevo čeká soumar. Prázdné údolí se táhne zpět kolem roztroušených stojících zlomků k plochým stolovým horám na obzoru. Všechno je v odstínech okru a rzi pod řídkou modrou oblohou a osamělé a rovné písky ze Shelleyho Ozymandiase se rozprostírají daleko do dálky."
